Thus, by triangle inequality,
\begin{align*}
  \|x_{k+1}^\delta-x_{k+1}\| &\leq \|x_k^\delta -x_k\|+\eta_k \|F_{i_k}'(x_k^\delta)^* - F_{i_k}'(x_k)^*\|\|F_{i_k}(x_k^\delta)-y_{i_k}^\delta\| \\
     & \quad +\|F_{i_k}'(x_k)^*\|\|((F_{i_k}(x_k^\delta)-y_{i_k}^\delta)-(F_{i_k}(x_k)-y_{i_k}))\|.
\end{align*}
Then the desired assertion follows from the continuity of the operators $F_i$ and $F_i'$ in Assumption \ref{ass:sol}(i)
and the induction hypothesis.
\end{proof}

source_units.raw_tex:
This work is concerned with the numerical solution of the system of nonlinear ill-posed operator equations
\begin{equation}\label{eqn:nonlin}
  F_i(x) = y_i^\dag,\quad i =1,\ldots, n,
\end{equation}
where each $F_i: \mathcal{D}(F_i)\to Y$ is a nonlinear mapping
with its domain $\mathcal{D}(F_i)\subset X$, and $X$ and $Y$ are Hilbert spaces with inner
products $\langle\cdot,\cdot\rangle$ and norms $\|\cdot\|$, respectively.
The number %$n\in\mathbb{N}$
$n$ of nonlinear equations in \eqref{eqn:nonlin} can potentially be very large.
The notation $y_i^\dag \in Y$ denotes the exact data (corresponding to the reference solution
$x^\dag\in X$ to be defined below, i.e., $y^\dag=F(x^\dag)$). Equivalently, problem \eqref{eqn:nonlin} can be rewritten as
\begin{equation}\label{eqn:nonlin-gen}
  F(x) = y^\dag,
\end{equation}
with the operator $F: X \to Y^n$ ($Y^n$ denotes the product space $Y\times \cdots \times Y$) and $y^\dag\in Y^n$ defined by
\begin{equation*}
  F(x)=\frac{1}{\sqrt{n}}\left(\begin{array}{c}F_1(x)\\ \ldots\\ F_n(x)\end{array}\right)\quad \mbox{and}\quad y^\dag=\frac{1}{\sqrt{n}}\left(\begin{array}{c}y_1^\dag\\ \ldots\\ y_n^\dag\end{array}\right),
\end{equation*}

respectively. The scaling $n^{-\frac12}$ above is introduced for the convenience of later discussions. In practice,
instead of the exact data $y^\dag$, we have access only to the noisy data $y^\delta$ of a noise level
$\delta\ge 0$, namely
\begin{equation*}
  \|y^\delta - y^\dag\| = \delta\,.
\end{equation*}

\begin{algorithm}
  \caption{Stochastic gradient method for problem \eqref{eqn:nonlin}.\label{alg:sgd}}
  \begin{algorithmic}[1]
    \STATE Given initial guess $x_1$.
    \FOR{$k=1,2,\ldots$}
      \STATE Randomly draw an index $i_k$;
      \STATE Update the iterate $x_k^\delta$ by
      \begin{equation}\label{eqn:sgd}
        x_{k+1}^\delta = x_k^\delta - \eta_k F_{i_k}'(x_k^\delta)^*(F_{i_k}(x_k^\delta)-y_{i_k}^\delta);
      \end{equation}
      \STATE Check the stopping criterion.
    \ENDFOR
  \end{algorithmic}
\end{algorithm}

\begin{assumption}\label{ass:sol}
The following conditions hold:
\begin{itemize}
  \item[$\rm(i)$] The operators $F_i$, $i=1,\ldots,n$, are continuous, with continuous and bounded derivatives on $X$.
  \item[$\rm(ii)$] There exists an $\eta\in(0,\frac12)$ such that for any $x,\tilde x\in X$,
  \begin{equation}\label{eqn:tangential-cone}
    \|F(x)-F(\tilde x)-F'(\tilde x)(x-\tilde x)\|\leq \eta\|F(x)-F(\tilde x)\|.
  \end{equation}
  \item[$\rm(iii)$] There are a family of uniformly bounded operators $R^i_x$ such that for any $x\in X$,
  \begin{equation*}
    F_i'(x) = R_x^iF_i'(x^\dag)
  \end{equation*}
  and $R_x=\mathrm{diag}(R_x^i):Y^n\to Y^n$, with {\rm(}with $\|\cdot\|$ denoting the operator norm on $Y^n${\rm)}
  \begin{equation*}
    \|R_x-I\|\leq c_R\|x-x^\dag\|.
  \end{equation*}
\item[$\rm(iv)$] The following source condition holds: there exist some $\nu\in (0,\frac12)$ and $w\in X$ such that
  \begin{equation*}
    x^\dag - x_1 = (F'(x^\dag)^*F'(x^\dag))^\nu w.
  \end{equation*}
\end{itemize}
\end{assumption}

\begin{assumption}\label{ass:stepsize}
The step sizes $\{\eta_k\}_{k\geq 1}$ satisfy one of the following properties.
\begin{itemize}
\item[$\rm(i)$] $\eta_k\max_i\sup_x\|F_i'(x)\|^2<1$ and $\sum_{k=1}^\infty \eta_k =\infty$.
\item[$\rm(ii)$] $\eta_k=\eta_0k^{-\alpha}$, with $\alpha\in(0,1)$ and $\eta_0\leq (\max_i\sup_x\|F_i'(x)\|^2)^{-1}$.
\end{itemize}
\end{assumption}

\begin{theorem}[convergence for noisy data]\label{thm:conv-noisy}
Let Assumptions \ref{ass:sol}(i)-(ii) and \ref{ass:stepsize}(i) be fulfilled. If the stopping index $k(\delta)\in\mathbb{N}$ is chosen such that
\begin{equation*}
  \lim_{\delta\to0^+}k(\delta)=\infty \quad\mbox{and}\quad \lim_{\delta\to0^+}\delta^2\sum_{i=1}^{k(\delta)}\eta_i = 0,
\end{equation*}
then there exists a solution $x^*\in X$ to problem \eqref{eqn:nonlin} such that
\begin{equation*}
  \lim_{\delta\to 0^+}\E[\|x_{k(\delta)}^\delta - x^*\|^2]=0.
\end{equation*}
Further, if $\mathcal{N}(F'(x^\dag))\subset\mathcal{N}(F'(x))$, then
\begin{equation*}
  \lim_{\delta\to0^+}\E[\|x_{k(\delta)}^\delta -x^\dag\|^2]=0.
\end{equation*}
\end{theorem}

Let Assumptions \ref{ass:sol}(i)-(ii) and \ref{ass:stepsize}(i) be fulfilled. If the stopping index $k(\delta)\in\mathbb{N}$ is chosen such that
\begin{equation*}
  \lim_{\delta\to0^+}k(\delta)=\infty \quad\mbox{and}\quad \lim_{\delta\to0^+}\delta^2\sum_{i=1}^{k(\delta)}\eta_i = 0,
\end{equation*}

By Proposition \ref{prop:mono-exact} and Young's inequality $2ab\leq \epsilon a^2 + \epsilon^{-1} b^2$,
with the choice $a=\E[\|F(x_k^\delta)-y^\delta\|^2]^\frac{1}{2}$, $b=(1+\eta)\delta$ and $\epsilon=1-2\eta>0$:
\begin{align*}
    & \E[\|x^*-x_{k+1}^\delta\|^2] - \E[\|x^*-x_{k}^\delta\|^2] \\
   \leq & -(1-2\eta)\eta_k\E[\|F(x_k^\delta)-y^\delta\|^2] +  2\eta_k(1+\eta)\delta\E[\|F(x_k^\delta)-y^\delta\|^2]^\frac{1}{2}
   \leq \frac{(1+\eta)^2}{1-2\eta}\eta_k\delta^2.
\end{align*}

Then for any $m<n$, summing the above inequality with $\delta=\delta_n$ from $k_m$ to $k_n-1$
(since $k_n$ is strictly increasing with $n$ by assumption) and applying the triangle inequality lead to
\begin{align*}
  \E[\|x_{k_n}^{\delta_n} -x^*\|^2] &\leq \E[\|x_{k_m}^{\delta_n}-x^*\|^2] + \frac{(1+\eta)^2}{1-2\eta}\delta_n^2\sum_{j=k_m}^{k_n-1}\eta_j\\
     & \leq 2\E[\|x_{k_m}^{\delta_n}-x_{k_m}\|^2] + 2\E[\|x_{k_m}-x^*\|^2] + \frac{(1+\eta)^2}{1-2\eta}\delta_n^2\sum_{j=1}^{k_n-1}\eta_j.
\end{align*}

\begin{lemma}\label{lem:linear}
Let Assumptions \ref{ass:sol}(i) and (ii) be fulfilled. Then the following statements hold.
\begin{itemize}
  \item[$\rm(i)$] The following inequalities hold:
  \begin{equation*}
  \frac{1}{1+\eta}\|F'(x)(x-\tilde x)\|\leq \|F(x)-F(\tilde x)\|\leq \frac{1}{1-\eta}\|F'(x)(x-\tilde x)\|.
  \end{equation*}
  \item[$\rm(ii)$]If $x^*$ is a solution of \eqref{eqn:nonlin}, then any other solution $\tilde x^*$ satisfies
$x^*-\tilde x^* \in \mathcal{N}(F'(x^*))$, and vice versa.
\end{itemize}
\end{lemma}

\begin{prop}\label{prop:mono-exact}
Let Assumptions \ref{ass:sol}(i)-(ii) and \ref{ass:stepsize}(i) be fulfilled. Then for any solution $x^*$ to problem \eqref{eqn:nonlin}, there holds
\begin{equation*}
  \E[\|x^*-x_{k+1}^\delta\|^2] - \E[\|x^*-x_{k}^\delta\|^2]
   \leq  -(1-2\eta)\eta_k\E[\|F(x_k^\delta)-y^\delta\|^2] + { 2\eta_k(1+\eta)\delta\E[\|F(x_k^\delta)-y^\delta\|^2]^\frac{1}{2}}.
\end{equation*}
\end{prop}

Completing the square gives
\begin{align*}
    \|x^*-x_{k+1}^\delta\|^2 - \|x^*-x_{k}^\delta\|^2 = & 2\langle x_k^\delta - x^*,x_{k+1}^\delta-x_k^\delta\rangle + \|x_{k+1}^\delta-x_k^\delta\|^2.
\end{align*}
By the definition of the SGD iterate $x_{k}^\delta$ in \eqref{eqn:sgd}, there holds
\begin{align*}
   & \|x^*-x_{k+1}^\delta\|^2 - \|x^*-x_{k}^\delta\|^2\\
  = & -2\eta_k\langle x_k^\delta-x^*,  F_{i_k}'(x_k^\delta)^*(F_{i_k}(x_k^\delta)-y_{i_k}^\delta)\rangle + \eta_k^2\| F_{i_k}'(x_k^\delta)^*(F_{i_k}(x_k^\delta)-y_{i_k}^\delta)\|^2 \\
  = & -2\eta_k\langle F_{i_k}'(x_k^\delta)(x_k^\delta-x^*), F_{i_k}(x_k^\delta)-y_{i_k}^\delta\rangle + \eta_k^2\|F_{i_k}'(x_k^\delta)^*(F_{i_k}(x_k^\delta)-y_{i_k}^\delta)\|^2.
\end{align*}

\begin{corollary}\label{cor:mono}
Let Assumptions \ref{ass:sol}(i)-(ii) and \ref{ass:stepsize}(i) be fulfilled. Then for the exact data $y^\dag$,
any solution $x^*$ to problem \eqref{eqn:nonlin} satisfies
\begin{align*}
   \E[\|x^*-x_{k+1}\|^2] - \E[\|x^*-x_{k}\|^2] &\leq -(1-2\eta)\eta_k\E[\|F(x_k)-y^\dag\|^2],\\
   \sum_{k=1}^\infty \eta_k\E[\|F(x_k)-y^\dag\|^2] &\leq \frac{1}{1-2\eta}\|x^*-x_1\|^2.
\end{align*}
%and
%\begin{equation*}
%  \sum_{k=1}^\infty \eta_k\E[\|F(x_k)-y^\dag\|^2] \leq \frac{1}{1-2\eta}\|x^*-x_1\|^2.
%\end{equation*}
\end{corollary}

\begin{lemma}\label{lem:Cauchy}
Let Assumptions \ref{ass:sol}(i)-(ii) and \ref{ass:stepsize}(i) be fulfilled. Then for the exact data $y^\dag$,
the sequence $\{x_k\}_{k\geq 1}$ generated by Algorithm \ref{alg:sgd} is a Cauchy sequence.
\end{lemma}

\begin{proof}
The argument below follows closely \cite[Theorem 2.3]{HankeNeubauerScherzer:1995}, which can be
traced back to \cite{McCormickRodrigue:1975}. Let $x^*$ be any solution to problem \eqref{eqn:nonlin}, and let $e_k:=x_k-x^*$. By
Corollary \ref{prop:mono-exact}, $\E[\|e_k\|^2]$ is monotonically decreasing to some $\epsilon\geq 0$.
Next we show that the sequence $\{x_k\}_{k\ge 1}$ is actually a Cauchy sequence. First we note that
$\E[\langle\cdot,\cdot\rangle]$ defines an inner product. For any $j\geq k$, choose an index $\ell$
with $j\geq \ell\geq k$ such that
\begin{equation}\label{eqn:minimal-res}
  \E[\|y^\dag - F(x_\ell)\|^2]\leq \E[\|y^\dag - F(x_i)\|^2], \quad \forall k\leq i \leq j.
\end{equation}
In light of the triangle inequality
\begin{equation*}
  \E[\|e_j-e_k\|^2]^\frac{1}{2} \leq \E[\|e_j-e_\ell\|^2]^\frac{1}{2} + \E[\|e_\ell-e_k\|^2]^\frac{1}{2},
\end{equation*}
and the trivial identities
\begin{equation}\label{eqn:err-exact}
\begin{aligned}
  \E[\|e_j-e_\ell\|^2] & = 2\E[\langle e_\ell-e_j,e_\ell\rangle] + \E[\|e_j\|^2] - \E[\|e_\ell\|^2],\\
  \E[\|e_\ell-e_k\|^2] & = 2\E[\langle e_\ell-e_k,e_\ell\rangle] + \E[\|e_k\|^2] - \E[\|e_\ell\|^2],
\end{aligned}
\end{equation}
it suffices to prove that both $\E[\|e_j-e_\ell\|^2]$ and $\E[\|e_\ell-e_k\|^2]$ on the left hand side tend to zero as $k\to \infty$.
For $k\to \infty$, the last two terms on each of the right hand side of \eqref{eqn:err-exact} tends to $\epsilon-\epsilon=0$, by
the monotone convergence of $\E[\|e_k\|^2]$ to $\epsilon$.
Next we show that the term $\E[\langle e_\ell-e_k,e_\ell\rangle]$ also tends to zero as $k\to\infty$.
Actually, by the definition of the SGD iterate $x_k$ in \eqref{eqn:sgd}, we have
\begin{equation*}
  e_\ell - e_k = \sum_{i=k}^{\ell-1}(e_{i+1}-e_i) = {\sum_{i=k}^{\ell-1}\eta_iF_{i_i}'(x_i)^*(y_{i_i}^\dag-F_{i_i}(x_i))}.
\end{equation*}
By the triangle inequality, we can bound $\E[\langle e_\ell-e_k,e_\ell\rangle]$ by
\begin{align*}
  |\E[\langle e_\ell-e_k,e_\ell\rangle]| & = |\E[\sum_{i=k}^{\ell-1}\langle \eta_iF_{i_i}'(x_i)^*(y_{i_i}^\dag-F_{i_i}(x_i)),e_\ell\rangle]|\\
  & \leq \sum_{i=k}^{\ell-1}\eta_i|\E[\langle F_{i_i}'(x_i)^*(y_{i_i}^\dag-F_{i_i}(x_i)),e_\ell\rangle]|\\
  & = \sum_{i=k}^{\ell-1}\eta_i|\E[\langle y_{i_i}^\dag-F_{i_i}(x_i),F_{i_i}'(x_i)(x^*-x_i+x_i-x_\ell)\rangle]|.
\end{align*}
Then by the Cauchy-Schwarz inequality and triangle inequality, we obtain
\begin{align*}
 |\E[\langle e_\ell-e_k,e_\ell\rangle]|
  & \leq \sum_{i=k}^{\ell-1}\eta_i|\E[\langle y^\dag-F(x_i),F'(x_i)(x^*-x_i+x_i-x_\ell)\rangle]|\\
  & \leq \sum_{i=k}^{\ell-1}\eta_i\E[\|y^\dag-F(x_i)\|^2]^\frac{1}{2}\E[\|F'(x_i)(x^*-x_i+x_i-x_\ell)\|^2]^\frac{1}{2}\\
  & \leq \sum_{i=k}^{\ell-1}\eta_i\E[\|y^\dag-F(x_i)\|^2]^\frac{1}{2}\E[\|F'(x_i)(x^*-x_i)\|^2]^\frac{1}{2}\\
   &\quad +\sum_{i=k}^{\ell-1}\eta_i\E[\|y^\dag-F(x_i)\|^2]^\frac{1}{2}\E[\|F'(x_i)(x_i-x_\ell)\|^2]^\frac{1}{2}
   :={\rm I} + {\rm II}.
\end{align*}
By Assumption \ref{ass:sol}(ii) and Lemma \ref{lem:linear}(i), we have
\begin{equation*}
\|F'(x)(x-\tilde x)\|\leq (1+\eta)\|F(x)-F(\tilde x)\|.
\end{equation*}
Substituting this inequality into the term $\rm I$ leads to
\begin{align*}
  {\rm I} & \leq (1+\eta)\sum_{i=k}^{\ell-1}\eta_i\E[\|y^\dag-F(x_i)\|^2]^\frac{1}{2}\E[\|F(x^*)-F(x_i)\|^2]^\frac{1}{2}
           = (1+\eta)\sum_{i=k}^{\ell-1}\eta_i\E[\|y^\dag-F(x_i)\|^2].
\end{align*}
Likewise, by the triangle inequality and the choice of the index $\ell$ in \eqref{eqn:minimal-res},
\begin{align*}
  {\rm II} & \leq (1+\eta)\sum_{i=k}^{\ell-1}\eta_i\E[\|y^\dag-F(x_i)\|^2]^\frac{1}{2}\E[\|F(x_\ell)-F(x_i)\|^2]^\frac{1}{2}\\
          & \leq (1+\eta)\sum_{i=k}^{\ell-1}\eta_i\E[\|y^\dag-F(x_i)\|^2] + (1+\eta)\sum_{i=k}^{\ell-1}\eta_i\E[\|y^\dag-F(x_i)\|^2]^\frac{1}{2}\E[\|F(x_\ell)-y^\dag\|^2]^\frac{1}{2}\\
          & \leq 2(1+\eta)\sum_{i=k}^{\ell-1}\eta_i\E[\|y^\dag-F(x_i)\|^2].
\end{align*}
The last two estimates together imply
\begin{align*}
  |\E[\langle e_\ell-e_k,e_\ell\rangle]| & \leq 3(1+\eta)\sum_{i=k}^{\ell-1}\eta_i\E[\|y^\dag-F(x_i)\|^2].
\end{align*}
Similarly, one can deduce
\begin{equation*}
  |\E[\langle e_j-e_\ell,e_\ell\rangle]| \leq 3(1+\eta)\sum_{i=\ell}^{j-1}\eta_i\E[\|y^\dag-F(x_i)\|^2].
\end{equation*}
These two estimates and Corollary \ref{prop:mono-exact} imply that the right hand sides of \eqref{eqn:err-exact}
tend to zero as $k\to\infty$. Thus, the sequence $\{e_k\}_{k\geq 1}$ and also $\{x_k\}_{k\geq1}$ are Cauchy sequences.
\end{proof}

In light of the triangle inequality
\begin{equation*}
  \E[\|e_j-e_k\|^2]^\frac{1}{2} \leq \E[\|e_j-e_\ell\|^2]^\frac{1}{2} + \E[\|e_\ell-e_k\|^2]^\frac{1}{2},
\end{equation*}
and the trivial identities
\begin{equation}\label{eqn:err-exact}
\begin{aligned}
  \E[\|e_j-e_\ell\|^2] & = 2\E[\langle e_\ell-e_j,e_\ell\rangle] + \E[\|e_j\|^2] - \E[\|e_\ell\|^2],\\
  \E[\|e_\ell-e_k\|^2] & = 2\E[\langle e_\ell-e_k,e_\ell\rangle] + \E[\|e_k\|^2] - \E[\|e_\ell\|^2],
\end{aligned}
\end{equation}
it suffices to prove that both $\E[\|e_j-e_\ell\|^2]$ and $\E[\|e_\ell-e_k\|^2]$ on the left hand side tend to zero as $k\to \infty$.
For $k\to \infty$, the last two terms on each of the right hand side of \eqref{eqn:err-exact} tends to $\epsilon-\epsilon=0$, by
the monotone convergence of $\E[\|e_k\|^2]$ to $\epsilon$.

Next we show that the term $\E[\langle e_\ell-e_k,e_\ell\rangle]$ also tends to zero as $k\to\infty$.
Actually, by the definition of the SGD iterate $x_k$ in \eqref{eqn:sgd}, we have
\begin{equation*}
  e_\ell - e_k = \sum_{i=k}^{\ell-1}(e_{i+1}-e_i) = {\sum_{i=k}^{\ell-1}\eta_iF_{i_i}'(x_i)^*(y_{i_i}^\dag-F_{i_i}(x_i))}.
\end{equation*}
By the triangle inequality, we can bound $\E[\langle e_\ell-e_k,e_\ell\rangle]$ by
\begin{align*}
  |\E[\langle e_\ell-e_k,e_\ell\rangle]| & = |\E[\sum_{i=k}^{\ell-1}\langle \eta_iF_{i_i}'(x_i)^*(y_{i_i}^\dag-F_{i_i}(x_i)),e_\ell\rangle]|\\
  & \leq \sum_{i=k}^{\ell-1}\eta_i|\E[\langle F_{i_i}'(x_i)^*(y_{i_i}^\dag-F_{i_i}(x_i)),e_\ell\rangle]|\\
  & = \sum_{i=k}^{\ell-1}\eta_i|\E[\langle y_{i_i}^\dag-F_{i_i}(x_i),F_{i_i}'(x_i)(x^*-x_i+x_i-x_\ell)\rangle]|.
\end{align*}

Then by the Cauchy-Schwarz inequality and triangle inequality, we obtain
\begin{align*}
 |\E[\langle e_\ell-e_k,e_\ell\rangle]|
  & \leq \sum_{i=k}^{\ell-1}\eta_i|\E[\langle y^\dag-F(x_i),F'(x_i)(x^*-x_i+x_i-x_\ell)\rangle]|\\
  & \leq \sum_{i=k}^{\ell-1}\eta_i\E[\|y^\dag-F(x_i)\|^2]^\frac{1}{2}\E[\|F'(x_i)(x^*-x_i+x_i-x_\ell)\|^2]^\frac{1}{2}\\
  & \leq \sum_{i=k}^{\ell-1}\eta_i\E[\|y^\dag-F(x_i)\|^2]^\frac{1}{2}\E[\|F'(x_i)(x^*-x_i)\|^2]^\frac{1}{2}\\
   &\quad +\sum_{i=k}^{\ell-1}\eta_i\E[\|y^\dag-F(x_i)\|^2]^\frac{1}{2}\E[\|F'(x_i)(x_i-x_\ell)\|^2]^\frac{1}{2}
   :={\rm I} + {\rm II}.
\end{align*}

By Assumption \ref{ass:sol}(ii) and Lemma \ref{lem:linear}(i), we have
\begin{equation*}
\|F'(x)(x-\tilde x)\|\leq (1+\eta)\|F(x)-F(\tilde x)\|.
\end{equation*}
Substituting this inequality into the term $\rm I$ leads to
\begin{align*}
  {\rm I} & \leq (1+\eta)\sum_{i=k}^{\ell-1}\eta_i\E[\|y^\dag-F(x_i)\|^2]^\frac{1}{2}\E[\|F(x^*)-F(x_i)\|^2]^\frac{1}{2}
           = (1+\eta)\sum_{i=k}^{\ell-1}\eta_i\E[\|y^\dag-F(x_i)\|^2].
\end{align*}

Likewise, by the triangle inequality and the choice of the index $\ell$ in \eqref{eqn:minimal-res},
\begin{align*}
  {\rm II} & \leq (1+\eta)\sum_{i=k}^{\ell-1}\eta_i\E[\|y^\dag-F(x_i)\|^2]^\frac{1}{2}\E[\|F(x_\ell)-F(x_i)\|^2]^\frac{1}{2}\\
          & \leq (1+\eta)\sum_{i=k}^{\ell-1}\eta_i\E[\|y^\dag-F(x_i)\|^2] + (1+\eta)\sum_{i=k}^{\ell-1}\eta_i\E[\|y^\dag-F(x_i)\|^2]^\frac{1}{2}\E[\|F(x_\ell)-y^\dag\|^2]^\frac{1}{2}\\
          & \leq 2(1+\eta)\sum_{i=k}^{\ell-1}\eta_i\E[\|y^\dag-F(x_i)\|^2].
\end{align*}

The last two estimates together imply
\begin{align*}
  |\E[\langle e_\ell-e_k,e_\ell\rangle]| & \leq 3(1+\eta)\sum_{i=k}^{\ell-1}\eta_i\E[\|y^\dag-F(x_i)\|^2].
\end{align*}
Similarly, one can deduce
\begin{equation*}
  |\E[\langle e_j-e_\ell,e_\ell\rangle]| \leq 3(1+\eta)\sum_{i=\ell}^{j-1}\eta_i\E[\|y^\dag-F(x_i)\|^2].
\end{equation*}
These two estimates and Corollary \ref{prop:mono-exact} imply that the right hand sides of \eqref{eqn:err-exact}
tend to zero as $k\to\infty$. Thus, the sequence $\{e_k\}_{k\geq 1}$ and also $\{x_k\}_{k\geq1}$ are Cauchy sequences.

\begin{lemma}\label{lemma:res}
Let Assumptions \ref{ass:sol}(i)-(ii) and \ref{ass:stepsize}(i) be fulfilled. Then for the exact data $y^\dag$, there holds
\begin{equation*}
  \lim_{k\to\infty} \E[\|F(x_k)-y^\dag\|^2] = 0.
\end{equation*}
\end{lemma}

\begin{proof}
By Lemma \ref{lem:Cauchy}, $\{x_k\}_{k\geq 1}$ is a Cauchy sequence. By Assumption \ref{ass:stepsize}(i),
$\sup_x\|F'(x)\|\leq \eta_0^{-\frac12}$. Further, for any $x,\tilde x\in X$, there holds
\begin{equation*}
  \|F(x)-F(\tilde x)\| \leq (1-\eta)^{-1}\|F'(x)(x-\tilde x)\|\leq (1-\eta)^{-1}\eta_0^{-\frac12}\|x-\tilde x\|.
\end{equation*}
Thus, $\{F(x_k)-y^\dag\}_{k\geq 1}$ is a Cauchy sequence, and $\E[\|F(x_k)-y^\dag\|^2]$
converges. Now we proceed by contradiction, and assume that $\lim_{k\to\infty}\E[\|F(x_k)-y^\dag\|^2]>0$.
Then there exist some $\epsilon>0$ and $k^*\in \mathbb{N}$, such that $\E[\|F(x_k)-y^\dag\|^2]\geq \epsilon$
for all $k\geq k^*$. Hence, by Assumption \ref{ass:stepsize}(i),
\begin{equation*}
  \sum_{k=1}^\infty \eta_k\E[\|F(x_k)-y^\dag\|^2] \geq \sum_{k=k^*}^\infty \eta_k\E[\|F(x_k)-y^\dag\|^2] \geq \epsilon\sum_{k=k^*}^\infty\eta_k =\infty,
\end{equation*}
which contradicts the inequality
\begin{equation*}
\sum_{k=1}^\infty \eta_k\E[\|F(x_k)-y^\dag\|^2] <\infty,
\end{equation*}
from Corollary \ref{cor:mono}. This completes the proof of the lemma.
\end{proof}

By Lemma \ref{lem:Cauchy}, $\{x_k\}_{k\geq 1}$ is a Cauchy sequence. By Assumption \ref{ass:stepsize}(i),
$\sup_x\|F'(x)\|\leq \eta_0^{-\frac12}$. Further, for any $x,\tilde x\in X$, there holds
\begin{equation*}
  \|F(x)-F(\tilde x)\| \leq (1-\eta)^{-1}\|F'(x)(x-\tilde x)\|\leq (1-\eta)^{-1}\eta_0^{-\frac12}\|x-\tilde x\|.
\end{equation*}
Thus, $\{F(x_k)-y^\dag\}_{k\geq 1}$ is a Cauchy sequence, and $\E[\|F(x_k)-y^\dag\|^2]$

converges. Now we proceed by contradiction, and assume that $\lim_{k\to\infty}\E[\|F(x_k)-y^\dag\|^2]>0$.
Then there exist some $\epsilon>0$ and $k^*\in \mathbb{N}$, such that $\E[\|F(x_k)-y^\dag\|^2]\geq \epsilon$
for all $k\geq k^*$. Hence, by Assumption \ref{ass:stepsize}(i),
\begin{equation*}
  \sum_{k=1}^\infty \eta_k\E[\|F(x_k)-y^\dag\|^2] \geq \sum_{k=k^*}^\infty \eta_k\E[\|F(x_k)-y^\dag\|^2] \geq \epsilon\sum_{k=k^*}^\infty\eta_k =\infty,
\end{equation*}
which contradicts the inequality
\begin{equation*}
\sum_{k=1}^\infty \eta_k\E[\|F(x_k)-y^\dag\|^2] <\infty,
\end{equation*}
from Corollary \ref{cor:mono}. This completes the proof of the lemma.

\begin{theorem}[Convergence for exact data]\label{thm:conv-exact}
Let Assumptions \ref{ass:sol}(i)-(ii) and \ref{ass:stepsize}(i) be fulfilled. Then for the exact data $y^\dag$, the sequence
$\{x_k\}_{k\geq1}$ by Algorithm \ref{alg:sgd} converges to a solution $x^*$ of problem \eqref{eqn:nonlin}:
\begin{equation*}
  \lim_{k\to\infty}\E[\|x_k-x^*\|^2] = 0.
\end{equation*}
 Further, if
$\mathcal{N}(F'(x^\dag))\subset\mathcal{N}(F'(x))$, then
\begin{equation*}
  \lim_{k\to\infty}\E[\|x_k -x^\dag\|^2]=0.
\end{equation*}
\end{theorem}

\begin{proof}
Since $\{x_k\}_{k\geq1}$ is a Cauchy sequence, there exists a limit of $\{x_k\}_{k\geq 1}$, denoted by $x^*$. Further,
$x^*$ is a solution, since the residual $\E[\|y^\dag-F(x_k)\|^2]$ converges to zero as $k\to\infty$, in view of Lemma \ref{lemma:res}.

Note that problem \eqref{eqn:nonlin} has a unique solution of minimal distance to the initial guess $x_1$ that satisfies
\begin{equation*}
  x^\dag - x_1\in\mathcal{N}(F'(x^\dag))^\perp;
\end{equation*}
see Lemma \ref{lem:linear}. If {$\mathcal{N}(F'(x^\dag))\subset \mathcal{N}(F'(x_k))$}
 for all $k=1,2,\ldots$, then clearly,
\begin{equation*}
  x_k-x_1\in\mathcal{N}(F'(x^\dag))^\perp,\quad k =1,2,\ldots.
\end{equation*}
Consequently,
\begin{equation*}
  x^\dag - x^* = x^\dag - x_1 + x_1-x^*\in\mathcal{N}(F'(x^\dag))^\perp.
\end{equation*}
This and the inequalities from Lemma \ref{lem:linear}(i) imply $x^*=x^\dag$, completing the proof.
\end{proof}

